INSERT INTO messages (message_date, message_text, link) VALUES
    ('2025-12-16', 'અક્ષરબ્રહ્મ સત્ર અમૂલ્ય તક છે. ચૂકશો નહીં.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20251216_brahmavidyapath_.jpg'),
    ('2025-12-17', 'બ્રહ્મરૂપ થવાય એ સાચો લાભ.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20251217_brahmavidyapath.jpg'),
    ('2025-12-18', 'નિષ્ઠા દૃઢ કરવી એ સૌથી મોટો નિયમ.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20251218_brahmavidyapath.jpg'),
    ('2025-12-19', 'सर्वोच्च आनंद प्राप्ति के विचार में है।', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20251219_brahmavidyapath.jpg'),
    ('2025-12-20', 'અક્ષરબ્રહ્મ સત્ર એટલે નિષ્ઠાની દૃઢતાનું પર્વ.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20251220_brahmavidyapath.jpg'),
    ('2025-12-21', 'મને પ્રગટ મળ્યા પુરુષોત્તમ આજ...', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20251221_brahmavidyapath_001.jpg'),
    ('2025-12-22', 'સત્પુરુષ કરે તે સારા માટે.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20251222_brahmavidyapath.jpg'),
    ('2025-12-23', 'અવગુણ ટાળવા – મહિમા.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20251223_brahmavidyapath.jpg'),
    ('2025-12-24', 'Never Worry, We Have God!', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20251224_brahmavidyapath.jpg'),
    ('2025-12-25', 'સત્સંગ કરાવવો એ શ્રેષ્ઠ સેવા છે.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20251225_brahmavidyapath.jpg'),
    ('2025-12-26', 'દાસભાવ = સાચો સત્સંગ.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20251226_brahmavidyapath.jpg'),
    ('2025-12-27', 'અક્ષરબ્રહ્મ સત્ર અક્ષરધામનું ભાતું છે.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20251227_brahmavidyapath.jpg'),
    ('2025-12-28', 'कथावार्ता सत्संग की नींव है।', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20251228_brahmavidyapath.jpg'),
    ('2025-12-29', 'પૂજા એ પ્રભુ મિલનની પળ છે.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20251229_brahmavidyapath.jpg'),
    ('2025-12-30', 'જે સંબંધમાં આવે – ભવસિંધુ તરી ગયો.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20251230_brahmavidyapath.jpg'),
    ('2025-12-31', 'એકાદશી મને પ્રિય છે.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20251231_brahmavidyapath.jpg'),
    ('2026-01-01', 'અંતર્દૃષ્ટિ એ જ સત્સંગ છે.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20260101_brahmavidyapath.jpg'),
    ('2026-01-02', 'મનનું મૂકે તે એકાંતિક.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20260102_brahmavidyapath.jpg'),
    ('2026-01-03', 'દર પૂનમે ભગવાનના દર્શને અવશ્ય જવું.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20260103_brahmavidyapath.jpg'),
    ('2026-01-04', 'આખા બ્રહ્માંડમાં સત્સંગ થશે.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20260104_brahmavidyapath.jpg'),
    ('2026-01-05', 'ગુરુ કહે તે ''હાજી, હાજી''.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20260105_brahmavidyapath.jpg'),
    ('2026-01-06', 'ઘરસભાથી સુખ, શાંતિ, રાજીપો અને મોક્ષ ચારેય મળે છે.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20260106_brahmavidyapath.jpg'),
    ('2026-01-07', 'જેટલી નિર્દોષબુદ્ધિ એટલી સત્સંગની શુદ્ધિ.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20260107_brahmavidyapath_16x9.jpg'),
    ('2026-01-08', 'સુખ અને દુઃખ ભગવાનની પ્રસાદી છે.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20260108_brahmavidyapath.jpg'),
    ('2026-01-09', 'સત્સંગ શિક્ષણ પરીક્ષા એ ગુરુપૂજન છે.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20260109_brahmavidyapath.jpg'),
    ('2026-01-10', 'સંપનો અભાવ = અનંત જન્મ!', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20260110_brahmavidyapath.jpg'),
    ('2026-01-11', 'સન્માન અને અપમાન બંને નાશવંત છે.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20260111_brahmavidyapath.jpg'),
    ('2026-01-12', 'ક્ષમા આધ્યાત્મિક ખજાનો છે.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20260112_brahmavidyapath.jpg'),
    ('2026-01-13', 'રાજીપો એ જ મોક્ષ.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20260113_brahmavidyapath.jpg'),
    ('2026-01-14', 'આ તો દેના બેંક છે, લેના બેંક નથી.', 'https://www.baps.org/Data/Sites/1/Media/GalleryImages/35634/WebImages/20260114_brahmavidyapath.jpg')
